1419: bool vehumet_supports_spell(spell_type spell)
1420: {
1421:     // Conjurations work by conjuring up a chunk of short-lived matter and
1422:     // propelling it towards the victim. This is the most popular way, but
1423:     // by no means it has a monopoly for being destructive.
1424:     // Vehumet loves all direct physical destruction.
1425:     return spell_typematch(spell, spschool::conjuration)
1426:            || (get_spell_flags(spell) & spflag::destructive);
1427: }
